public class RectangleTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Rectangle r = new Rectangle(3.0, 4.0);
        check("getWidth()", 3.0, r.getWidth());
        check("getHeight()", 4.0, r.getHeight());
        check("area() of 3x4", 12.0, r.area());
        check("perimeter() of 3x4", 14.0, r.perimeter());
        Rectangle square = new Rectangle(2.5, 2.5);
        check("area() of 2.5x2.5", 6.25, square.area());
        check("perimeter() of 2.5x2.5", 10.0, square.perimeter());
        Rectangle thin = new Rectangle(0.5, 8.0);
        check("area() of 0.5x8", 4.0, thin.area());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

